
/* MAXLOW V2 - SAFE GLOBAL WALLPAPER */
html, body {
  background-image: url(https://imglink.cc/cdn/9g3W-8hfsf.png) !important;
  background-repeat: no-repeat !important;
  background-size: 100% 100% !important;
  background-position: center center !important;
  background-attachment: fixed !important;
}


/* MAXLOW V2:
   Legacy Maxlow match styling is deliberately scoped to pages containing
   the Autodarts match dartboard. This prevents old Chakra selectors from
   hijacking the new V2 power/account drawer on Home. */
@scope (:root:has(.css-1cdcn26)) {
:root {
  /*--color-bg-main: linear-gradient(135deg, #2b0000, #3b0a0a);*/
  /*--color-bg-box: linear-gradient(145deg, #4a0f0f, #5c1a1a);*/
  /*--color-border: #ff6b6b;*/
  /*--color-border: #ffffff;*/
  --color-text: #ffecec;
  --color-text-soft: #ffb3b3;
  /*--color-shadow: 0 0 10px #ff6b6b;
  --color-shadow-strong: 0 0 20px #ff6b6b;*/
  --color-shadow: 0 0 0px #ffffff;
  /*--color-shadow-strong: 0 0 20px #ffffff;*/
  --font-main: 'Tahoma', sans-serif;
  --spacing-player: 20px;
  --color-bg-box: linear-gradient(
  145deg,
  rgba(0, 0, 0, 0.),
  rgba(0, 0, 0, 0.)
);

  /* Softer Around the World target effect */
  --atw-target-low: #c7a800;
  --atw-target-high: #eadb55;
  --atw-target-stroke: #fff3b0;
  --atw-glow-low: rgba(255, 215, 0, 0.32);
  --atw-glow-high: rgba(255, 230, 90, 0.48);
}


/* --- Main Container --- */
:root:not(:has(.css-rc3vw3)) .css-tkevr6 {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 10px;
  box-sizing: border-box;
  background: var(--color-bg-main);
  color: var(--color-text);
  font-family: var(--font-main);
}

/* --- Shared Base Style for All Player Boxes --- */
:root:not(:has(.css-rc3vw3)) .css-rtn29s,
:root:not(:has(.css-rc3vw3)) .css-hjw8x4 {
  background: rgba(5, 10, 20, 0.45) !important;
  backdrop-filter: blur(12px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(12px) saturate(140%) !important;

  color: var(--color-text);
  padding: 1rem;
  box-sizing: border-box;
  border: 2px solid rgba(255,255,255,0.12);
  box-shadow: var(--color-shadow);
  transition: all 0.3s ease;
  border-radius: 12px;
  z-index: 10;
  position: absolute;
  width: 250px;
  height: calc((100% - 180px) / 3);
  overflow: hidden;
}

/* ========================= */
/* 1-2 Players: no height adjustment */
/* ========================= */
:root:not(:has(.css-rc3vw3)) #ad-ext-player-display > div:nth-child(1):only-child {
    top: 90px;
    left: 60px;
    height: calc(100% - 330px);

   
}

:root:not(:has(.css-rc3vw3)) #ad-ext-player-display > div:nth-child(1):nth-last-child(2) {
  top: 90px;
  left: 60px;
  height: calc(100% - 200px);
}
:root:not(:has(.css-rc3vw3)) #ad-ext-player-display > div:nth-child(2):nth-last-child(1) {
  top: 90px;
  right: 60px;
  height: calc(100% - 200px);
}

/* Player Name Position for 1-2 Players */
